& {  = Start-Process -FilePath 'C:\Python311\python.exe' -ArgumentList @('-m','PyInstaller','--onefile','--noconsole','--name','D2InventoryScanner','--add-data','tooltip_best_v6.pt;.','--collect-all','ultralytics','main.py') -PassThru;  = Get-Date; while (-not .HasExited) { if ((Get-Date) - ).TotalSeconds -gt 120 { break }; Start-Sleep -Seconds 5 }; if (.HasExited) { if (Test-Path 'dist\D2InventoryScanner.exe') { Write-Host 'EXE_READY' } else { Write-Host 'BUILD_FAILED' } } else { Write-Host 'TIMEOUT' } } 
